"""Plain-text and Markdown views of the registry and of a refetch."""

from __future__ import annotations

from collections.abc import Sequence

from crashcourt.clauses.registry import ClauseRegistry
from crashcourt.clauses.snapshot import DriftReport

MARKDOWN_HEADER = (
    "# Clause registry\n\n"
    "Generated by `crashcourt clauses list --markdown`; do not edit by hand.\n\n"
    "| ID | Polarity | Title | Source | Retrieved |\n"
    "| --- | --- | --- | --- | --- |\n"
)


def _cell(text: str) -> str:
    return text.replace("|", "\\|")


def listing_markdown(registry: ClauseRegistry) -> str:
    rows = [
        f"| {c.id} | {c.polarity} | {_cell(c.title)} | {c.source_url} | {c.retrieved} |\n"
        for c in registry
    ]
    return MARKDOWN_HEADER + "".join(rows)


def listing_text(registry: ClauseRegistry) -> str:
    width = max((len(c.id) for c in registry), default=0)
    return "".join(
        f"{c.id.ljust(width)}  {c.polarity:<10}  {c.retrieved}  {c.source_url}\n" for c in registry
    )


def drift_text(reports: Sequence[DriftReport]) -> str:
    width = max((len(r.clause_id) for r in reports), default=0)
    lines: list[str] = []
    for r in reports:
        name = r.clause_id.ljust(width)
        if r.error is not None:
            lines.append(f"ERROR  {name}  fetch failed: {r.error}")
            continue
        if r.actual_sha256 == r.expected_sha256:
            lines.append(f"ok     {name}  hash matches")
        else:
            lines.append(
                f"DRIFT  {name}  sha256 {r.actual_sha256} != recorded {r.expected_sha256}; "
                f"re-read {r.url}"
            )
        lines.extend(f"QUOTE  {name}  not found in the source: {q!r}" for q in r.missing_quotes)
        if r.missing_anchor is not None:
            lines.append(f"ANCHOR {name}  #{r.missing_anchor} matches no heading on the page")
    unreachable = sum(r.error is not None for r in reports)
    unchanged = sum(r.ok for r in reports)
    drifted = len(reports) - unreachable - unchanged
    lines.append(
        f"refetch: {unchanged} unchanged, {drifted} drifted, {unreachable} unreachable "
        "(reported for review; never fatal)"
    )
    return "\n".join(lines) + "\n"
